$(document).on("keyup", "#capital-form input", function (e) {
    getCapitalSum()
});

function getCapitalSum(){
    var form = $('#capital-form');
    var table = $('#capital-table');
    var authorizedsharevalue = paidupcapital = paidupshareqty = shareqty = capital = 0;
    var authorizedcapital = (isNumber($('#authorizedcapital').val()))?parseFloat($('#authorizedcapital').val()):0;
    var authorizedshareqty = (isNumber($('#authorizedshareqty').val()))?parseFloat($('#authorizedshareqty').val()):0;

    if(authorizedshareqty > 0 && authorizedcapital > 0){
        authorizedsharevalue = authorizedcapital / authorizedshareqty;
    }
    $('#authorizedsahrevalue').val(authorizedsharevalue.toFixed(2));

    $('#capital-table .paidupshare').attr('max',authorizedshareqty);
    $('#capital-table .paidupcapital').attr('max',authorizedcapital);

    $('#capital-table .capital').attr('max',authorizedcapital);
    $('#capital-table .capital').attr('max',authorizedcapital);

    table.find('tbody').find('tr').find('.capital').each(function() {
        capital = (isNumber($(this).val()))?parseFloat($(this).val()):0;
        paidupcapital += capital;
    });

    table.find('tbody').find('tr').each(function() {
        capital = (isNumber($(this).find('.capital').val()))?parseFloat($(this).find('.capital').val()):0;
        shareqty = (authorizedshareqty * capital)/paidupcapital;
        $(this).find('.shareqty').val(shareqty);
        paidupshareqty += shareqty;
    });

    $('#paidupshareqty').val(paidupshareqty);
    $('#paidupcapital').val(paidupcapital);

    if(paidupshareqty > 0){
        paidupsharevalue = paidupcapital / paidupshareqty;
        $('#paidupsharevalue').val(paidupsharevalue);
    }
}